const envelope = $json;

if (!envelope || envelope.success !== true) {
  throw new Error(
    'A API não confirmou a reserva do job visual.'
  );
}

if (envelope.empty || !envelope.data) {
  return [];
}

const data = envelope.data;

if (
  !data.job?.id ||
  !data.channel?.id ||
  !data.format?.key ||
  !data.approved_copy?.content
) {
  throw new Error(
    'O job visual reservado está incompleto.'
  );
}

return [{ json: data }];

const data = $json;
const format = data.format || {};
const campaign = data.campaign || {};
const channel = data.channel || {};
const product = data.product || {};
const copy = data.approved_copy?.content || {};

const sizes = {
  square: '1024x1024',
  feed_portrait: '1024x1536',
  story: '1024x1536',
  landscape: '1536x1024'
};

const formatNames = {
  square: 'fotografia quadrada de produto',
  feed_portrait: 'fotografia vertical de produto',
  story: 'fotografia vertical para Story ou Reels',
  landscape: 'fotografia horizontal de produto'
};

const media = Array.isArray(data.product_media)
  ? data.product_media
  : [];

const referenceMedia = media
  .filter(item =>
    /^https:\/\/.+/i.test(
      String(item.public_url || '').trim()
    )
  )
  .filter(
    (item, index, items) =>
      items.findIndex(
        candidate =>
          String(candidate.public_url).trim() ===
          String(item.public_url).trim()
      ) === index
  )
  .slice(0, 4);

const referenceUrls = referenceMedia.map(
  item => String(item.public_url).trim()
);

if (referenceUrls.length === 0) {
  throw new Error(
    'CREATIVE_IMAGE_REAL_REFERENCE_REQUIRED: ' +
    'cadastre pelo menos uma foto real do produto.'
  );
}

const referenceInventory = referenceMedia.map(
  (item, index) => ({
    order: index + 1,
    role:
      index === 0
        ? 'primary_identity_reference'
        : 'supporting_inspection_reference',
    url: String(item.public_url).trim(),
    alt_text: String(item.alt_text || '').trim() || null,
    is_primary: Boolean(item.is_primary)
  })
);

const prompt = [
  'MODO OBRIGATÓRIO: FOTOGRAFIA PREMIUM DE PRODUTO REAL.',
  'Edite e apresente o produto das fotografias fornecidas. Não crie um produto novo inspirado nelas.',
  'A IMAGEM DE REFERÊNCIA 1 é a âncora principal de identidade e geometria.',
  'As demais imagens servem somente para inspecionar laterais, portas, plugues, cabos, conectores, embalagem e acessórios.',
  'Nunca misture produtos, variantes, ângulos ou acessórios de fotografias diferentes.',
  'Preserve exatamente formato, proporção, cor, acabamento, textura, quantidade e tipo de portas, plugue, cabos, conectores, botões, marcações e acessórios reais.',
  'Não invente, remova, duplique, mova ou redesenhe portas, conectores, cabos, plugues, telas, botões, selos, marcas ou acessórios.',
  'Se uma característica não estiver comprovada nas referências, não a mostre.',
  'Não altere logotipo, texto impresso, símbolos ou numeração existentes no próprio produto.',
  'Não acrescente título, preço, CTA, selo, legenda, marca dágua ou qualquer texto publicitário.',
  'Não use mãos, pessoas, objetos decorativos que encostem no produto ou elementos que escondam suas características.',
  'Mantenha o produto inteiro dentro da área segura, sem cortes, deformações ou perspectiva impossível.',
  'Faça apenas tratamento fotográfico profissional: recorte limpo, fundo premium, iluminação de estúdio, sombra fisicamente coerente, reflexos controlados, contraste e nitidez.',
  'Fundo elegante, limpo e discreto em preto, grafite ou cinza premium, sem poluição visual.',
  'O resultado deve parecer fotografia comercial real feita em estúdio, nunca ilustração, render 3D ou produto redesenhado.',
  'Formato: ' + (formatNames[format.key] || format.key) + '.',
  'Dimensão final esperada: ' + format.width + 'x' + format.height + '.',
  product.name
    ? 'Nome cadastrado do produto: ' + product.name + '.'
    : '',
  product.description
    ? 'Descrição cadastrada, somente como contexto factual: ' +
      product.description + '.'
    : '',
  copy.headline
    ? 'Contexto comercial interno, não escrever na imagem: ' +
      copy.headline + '.'
    : '',
  'Antes de finalizar, conte visualmente portas, plugues, cabos, conectores e acessórios e compare com todas as referências.',
  'Se não for possível preservar o produto com fidelidade, não improvise.'
].filter(Boolean).join('\n');

const content = [
  {
    type: 'input_text',
    text: prompt
  },
  ...referenceUrls.flatMap((url, index) => [
    {
      type: 'input_text',
      text:
        index === 0
          ? 'IMAGEM DE REFERÊNCIA 1 - IDENTIDADE PRINCIPAL DO PRODUTO REAL'
          : 'IMAGEM DE REFERÊNCIA ' +
            (index + 1) +
            ' - INSPEÇÃO COMPLEMENTAR DO MESMO PRODUTO'
    },
    {
      type: 'input_image',
      image_url: url,
      detail: index === 0 ? 'high' : 'low'
    }
  ])
];

return [{
  json: {
    ...data,
    worker_id:
      'n8n-central-criativos-imagens-fidelidade-v2',
    visual_mode: 'premium_product_photo',
    fidelity_pipeline_version: '2.1',
    image_prompt: prompt,
    reference_urls: referenceUrls,
    reference_inventory: referenceInventory,
    openai_request: {
      model: 'gpt-5.4',
      input: [{
        role: 'user',
        content
      }],
      tools: [{
        type: 'image_generation',
        quality: 'high',
        size:
          sizes[format.key] ||
          '1024x1024'
      }]
    }
  }
}];

const source =
  $('Preparar Criativo Visual').first().json;

const response = $json;

const calls = Array.isArray(response.output)
  ? response.output.filter(
      item =>
        item &&
        item.type === 'image_generation_call' &&
        typeof item.result === 'string'
    )
  : [];

if (!calls.length) {
  const message =
    response.error?.message ||
    response.output_text ||
    'A OpenAI não retornou uma imagem.';

  throw new Error(message);
}

const imageBase64 = calls[0].result;

if (imageBase64.length < 100) {
  throw new Error(
    'A imagem retornada está vazia ou inválida.'
  );
}

const auditPrompt = [
  'Atue como inspetor técnico visual rigoroso de produto para comércio eletrônico.',
  'Compare as FOTOS REAIS DE REFERÊNCIA com a IMAGEM GERADA.',
  'Reprove se existir qualquer alteração física ou visual relevante.',
  'Verifique identidade do produto, formato, proporção, cor, acabamento, quantidade e tipo de portas, plugue, cabos, conectores, botões, marcações, embalagem e acessórios.',
  'Reprove porta extra, porta ausente, conector errado, cabo duplicado, acessório inventado, logotipo alterado, texto publicitário, deformação, corte ou produto diferente.',
  'Não premie beleza quando a fidelidade estiver errada.',
  'Quando embalagem ou acessório não aparecer na imagem gerada, marque o check como true somente se nada tiver sido inventado e a ausência não alterar a identidade do produto.',
  'Não reprove apenas porque uma embalagem opcional ficou fora da composição; reprove se ela aparecer alterada, inventada ou com marcações falsas.',
  'passed só pode ser true quando score for pelo menos 92, critical_issues estiver vazio e todos os checks forem true.',
  'Responda apenas JSON válido nesta estrutura:',
  JSON.stringify({
    passed: false,
    score: 0,
    critical_issues: [],
    differences: [],
    checks: {
      same_product: false,
      shape_and_proportion_match: false,
      color_and_finish_match: false,
      ports_match: false,
      plug_match: false,
      cables_and_connectors_match: false,
      accessories_match: false,
      branding_and_markings_match: false,
      packaging_match: false,
      no_added_advertising_text: false,
      product_not_cropped_or_deformed: false,
      photographic_realism: false
    },
    summary: ''
  })
].join('\n');

const auditContent = [
  {
    type: 'input_text',
    text: auditPrompt
  },
  ...source.reference_urls.flatMap(
    (url, index) => [
      {
        type: 'input_text',
        text:
          'FOTO REAL DE REFERÊNCIA ' +
          (index + 1)
      },
      {
        type: 'input_image',
        image_url: url,
        detail: index === 0 ? 'high' : 'low'
      }
    ]
  ),
  {
    type: 'input_text',
    text:
      'IMAGEM GERADA QUE DEVE SER AUDITADA'
  },
  {
    type: 'input_image',
    image_url:
      'data:image/png;base64,' +
      imageBase64,
    detail: 'high'
  }
];

return [{
  json: {
    ...source,
    image_base64: imageBase64,
    generation_response_id:
      response.id || null,
    generation_response_model:
      response.model || 'gpt-5.4',
    generation_usage:
      response.usage || null,
    fidelity_audit_request: {
      model: 'gpt-5.4',
      reasoning: {
        effort: 'medium'
      },
      max_output_tokens: 2500,
      text: {
        format: {
          type: 'json_object'
        }
      },
      input: [{
        role: 'user',
        content: auditContent
      }]
    }
  }
}];

let source = {};

try {
  source =
    $('Preparar Criativo Visual').first().json;
} catch {}

const incoming = $json || {};

const error =
  incoming.error ||
  incoming.cause ||
  incoming;

const message = String(
  error.message ||
  error.description ||
  error.error?.message ||
  'Falha não identificada na geração da imagem.'
).slice(0, 2000);

if (!source.job?.id) {
  throw new Error(
    'Não foi possível identificar o job visual com falha: ' +
    message
  );
}

const isRateLimited =
  /too many requests|rate limit|http 429/i.test(
    message
  );

const isFidelityRejection =
  message.includes(
    'CREATIVE_IMAGE_FIDELITY_REJECTED'
  ) ||
  message.includes(
    'CREATIVE_IMAGE_FIDELITY_AUDIT_INVALID'
  );

return [{
  json: {
    job_id: source.job.id,
    worker_id:
      source.worker_id ||
      'n8n-central-criativos-imagens-fidelidade-v2',
    error_code:
      isRateLimited
        ? 'OPENAI_IMAGE_RATE_LIMITED'
        : isFidelityRejection
          ? 'CREATIVE_IMAGE_FIDELITY_REJECTED'
          : 'OPENAI_IMAGE_GENERATION_FAILED',
    error_message: message,
    output: {
      failed_at:
        new Date().toISOString(),
      format_key:
        source.format?.key || null,
      visual_mode:
        source.visual_mode || null,
      pipeline:
        'premium-product-fidelity-v2.1',
      details: message
    }
  }
}];

const source =
  $('Validar Imagem Gerada').first().json;

const response = $json;

function extractText(value) {
  if (
    typeof value?.output_text === 'string' &&
    value.output_text.trim()
  ) {
    return value.output_text.trim();
  }

  if (Array.isArray(value?.output)) {
    return value.output
      .flatMap(item =>
        Array.isArray(item?.content)
          ? item.content
          : []
      )
      .map(item =>
        typeof item?.text === 'string'
          ? item.text
          : ''
      )
      .filter(Boolean)
      .join('')
      .trim();
  }

  return '';
}

let audit;

try {
  audit = JSON.parse(extractText(response));
} catch {
  throw new Error(
    'CREATIVE_IMAGE_FIDELITY_AUDIT_INVALID: ' +
    'a auditoria visual não retornou JSON válido.'
  );
}

const score = Number(audit.score || 0);

const criticalIssues = Array.isArray(
  audit.critical_issues
)
  ? audit.critical_issues
      .map(item => String(item))
      .filter(Boolean)
  : [];

const differences = Array.isArray(
  audit.differences
)
  ? audit.differences
      .map(item => String(item))
      .filter(Boolean)
  : [];

const checks =
  audit.checks &&
  typeof audit.checks === 'object' &&
  !Array.isArray(audit.checks)
    ? audit.checks
    : {};

const requiredChecks = [
  'same_product',
  'shape_and_proportion_match',
  'color_and_finish_match',
  'ports_match',
  'plug_match',
  'cables_and_connectors_match',
  'accessories_match',
  'branding_and_markings_match',
  'packaging_match',
  'no_added_advertising_text',
  'product_not_cropped_or_deformed',
  'photographic_realism'
];

const failedChecks = requiredChecks.filter(
  key => checks[key] !== true
);

const passed =
  audit.passed === true &&
  score >= 92 &&
  criticalIssues.length === 0 &&
  failedChecks.length === 0;

const normalizedAudit = {
  passed,
  score,
  critical_issues: criticalIssues,
  differences,
  failed_checks: failedChecks,
  checks,
  summary:
    typeof audit.summary === 'string'
      ? audit.summary.trim()
      : '',
  audit_response_id:
    response.id || null,
  audit_model:
    response.model || 'gpt-5.4',
  audited_at:
    new Date().toISOString()
};

if (!passed) {
  const details = [
    normalizedAudit.summary,
    criticalIssues.join('; '),
    failedChecks.length
      ? 'Falhas: ' + failedChecks.join(', ')
      : '',
    differences.join('; ')
  ]
    .filter(Boolean)
    .join(' | ')
    .slice(0, 1600);

  throw new Error(
    'CREATIVE_IMAGE_FIDELITY_REJECTED: ' +
    (details ||
      'a imagem não atingiu a fidelidade mínima.')
  );
}

return [{
  json: {
    job_id: source.job.id,
    worker_id: source.worker_id,
    channel_id: source.channel.id,
    format_key: source.format.key,
    image_base64: source.image_base64,
    prompt: source.image_prompt,
    content: {
      headline:
        source.approved_copy?.content?.headline ||
        null,
      primary_text:
        source.approved_copy?.content
          ?.primary_text || null,
      description:
        source.approved_copy?.content
          ?.description || null,
      cta:
        source.approved_copy?.content?.cta ||
        null
    },
    metadata: {
      generator:
        'openai-responses-image-generation',
      pipeline:
        'premium-product-fidelity-v2.1',
      visual_mode:
        source.visual_mode,
      generation_response_id:
        source.generation_response_id,
      generation_response_model:
        source.generation_response_model,
      generation_usage:
        source.generation_usage || null,
      fidelity_audit_usage:
        response.usage || null,
      reference_urls:
        source.reference_urls,
      reference_inventory:
        source.reference_inventory,
      requested_width:
        source.format.width,
      requested_height:
        source.format.height,
      fidelity_validation:
        normalizedAudit
    },
    output: {
      openai_response_id:
        source.generation_response_id,
      fidelity_audit_response_id:
        response.id || null,
      fidelity_score:
        score,
      generated_at:
        new Date().toISOString()
    }
  }
}];
